#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        cin >> l[i];
        l[i] %= k;
    }

    if (n == 1) {
        cout << l[0] << "\n";
        return 0;
    }

    vector<int> half1(l.begin(), l.begin() + n / 2);
    vector<int> half2(l.begin() + n / 2, l.end());

    unordered_set<int> set1, set2, temp_set2;

    for (int val : half1) {
        for (int prev : set1) {
            set2.insert((prev + val) % k);
        }
        set1.insert(val);
        for (int prev : set2) {
            set1.insert(prev);
        }
        set2.clear();
    }

    for (int val : half2) {
        for (int prev : set2) {
            set2.insert((prev + val) % k);
        }
        for (int prev : set1) {
            set2.insert(prev);
        }
    }

    std::vector<int> s_list(set1.begin(), set1.end());
    std::vector<int> s1_list(set2.begin(), set2.end());

    std::sort(s_list.begin(), s_list.end());
    std::sort(s1_list.begin(), s1_list.end());

    int max_val = std::max(s_list.back(), s1_list.back());
    int answer = max_val;

    for (int s_elem : s_list) {
        int target = k - 1 - s_elem;
        auto it = std::upper_bound(s1_list.begin(), s1_list.end(), target);
        if (it != s1_list.begin()) {
            int r = *(it - 1);
            int rt = s1_list.back();
            int candidate1 = (r + s_elem) % k;
            int candidate2 = (s_elem + rt) % k;
            answer = std::max({answer, candidate1, candidate2});
        }
    }

    cout << answer << "\n";

    return 0;
}
